// Extract LinkedIn profile URLs from Google search results
const items = $input.all();
const profiles = [];

for (const item of items) {
  if (item.json.items) {
    for (const result of item.json.items) {
      const url = result.link;
      const title = result.title;
      const snippet = result.snippet;

      // Extract name from title (usually "Name - Title | LinkedIn")
      const nameParts = title.split(' - ')[0] || title.split(' | ')[0];
      const name = nameParts.trim();

      // Try to extract job title
      let jobTitle = '';
      if (title.includes(' - ')) {
        const titleParts = title.split(' - ');
        if (titleParts.length > 1) {
          jobTitle = titleParts[1].split(' | ')[0].trim();
        }
      }

      // Extract from snippet if not found in title
      if (!jobTitle && snippet) {
        const snippetLower = snippet.toLowerCase();
        if (snippetLower.includes('recruiter') || 
            snippetLower.includes('talent') || 
            snippetLower.includes('hr') ||
            snippetLower.includes('hiring')) {
          jobTitle = snippet.split('.')[0].trim();
        }
      }

      profiles.push({
        name: name,
        title: jobTitle || 'HR Professional',
        profile_url: url,
        snippet: snippet,
        source: 'google_search'
      });
    }
  }
}

return profiles.map(p => ({ json: p }));

