parameters.functionCode:
// Parse AI-generated message and combine with profile data
const profile = $('Normalize Profile Data').item.json;
const aiResponse = $input.item.json.message?.content || $input.item.json.text || $input.item.json.choices?.[0]?.message?.content || '';
const inputParams = $('Parse Input Parameters').item.json;
const projects = JSON.parse(inputParams.your_projects);

// Try to split into connection request and follow-up message
let connectionRequest = '';
let followUpMessage = '';

if (aiResponse.includes('Connection Request')) {
  const parts = aiResponse.split('Follow-up Message');
  connectionRequest = parts[0].replace('Connection Request', '').replace(/[*:]/g, '').trim();
  followUpMessage = parts[1] ? parts[1].replace(/[*:]/g, '').trim() : aiResponse;
} else {
  // If no split, use first 280 chars for connection, rest for follow-up
  connectionRequest = aiResponse.substring(0, 280).trim();
  followUpMessage = aiResponse;
}

// Clean up any markdown or extra formatting
connectionRequest = connectionRequest.replace(/\[|\]/g, '').replace(/\n\n/g, '\n').trim();
followUpMessage = followUpMessage.replace(/\[|\]/g, '').replace(/\n\n\n/g, '\n\n').trim();

return {
  // Profile data
  name: profile.name,
  first_name: profile.name.split(' ')[0],
  title: profile.title,
  company: profile.company,
  location: profile.location,
  profile_url: profile.profile_url,

  // Your data
  your_name: inputParams.your_name,
  your_role: inputParams.your_role,
  your_experience: inputParams.your_experience,
  your_skills: inputParams.your_skills,
  your_projects: projects,

  // Generated messages
  connection_request: connectionRequest,
  follow_up_message: followUpMessage,

  // Metadata
  char_count_connection: connectionRequest.length,
  char_count_followup: followUpMessage.length,
  generated_at: new Date().toISOString(),
  ai_provider: 'openai' // or anthropic depending on which is enabled
};

